mapper.select:
select * from ( select hmr.marketing_report_id,hmr.marketing_report_number,hmr.marketing_report_name,hmr.credit_flag,(SELECT v.meaning FROM sys_code_value_b_v v WHERE v.CODE = 'SYS.YES_NO' AND hmr.credit_flag = v.CODE_VALUE)credit_flag_n,hmr.creation_date as created_date,hmr.created_by, (select wm_concat(hbm.bp_name) from hls_bp_master hbm,HLS_MARKETING_REPORT_bp hmrb where hbm.bp_id = hmrb.bp_id and hmrb.marketing_report_id = hmr.marketing_report_id and hmrb.bp_type in ('TENANT','TENANT_SEC','ASSET_TRANSFEROR','ACCOUNTS_RECEIVABLE')) tenant, (select v.meaning from sys_code_value_b_v v where v.code = 'HLS200.LEASING_PRODUCT_DETAIL' and hmr.apply_leasing_products = v.CODE_VALUE)apply_leasing_products_n, (select wm_concat(hbm.bp_name) from hls_bp_master hbm,HLS_MARKETING_REPORT_bp hmrb where hbm.bp_id = hmrb.bp_id and hmrb.marketing_report_id = hmr.marketing_report_id and hmrb.bp_type = 'WARRANTOR') other_bp_name, hmr.unit_id, (select fou.unit_name from fnd_org_unit fou where fou.unit_id=hmr.unit_id) as unit_id_n, nvl(hmr.estimated_financing_amount,(select q.FINANCE_AMOUNT from prj_quotation q where q.source_document_id = hmr.marketing_report_id and q.SOURCE_DOCUMENT_CATEGORY = 'HLS_MARKETING_REPORT'))estimated_financing_amount, hmr.creation_date as approved_date, hmr.approved_date+31 failure_date, hmr.apply_leasing_products, hmr.host_department_proportion, hmr.assist_department_proportion, hmr.host_project_manager, hmr.assist_project_manager, hmr.status, (SELECT meaning from sys_code_value_b_v where code = 'HLS_MARKETING' and code_value = hmr.status) status_n, TABALL1.NAME AS host_project_manager_n, TABALL1.UNIT_NAME host_unit_name, TABALL2.NAME AS assist_project_manager_n, TABALL2.UNIT_NAME assist_unit_name, hmr.creation_date, hmr.change_req_id from hls_marketing_report hmr left join ( SELECT FE. NAME, SUA.USER_ID, MIN(FOU.UNIT_NAME) UNIT_NAME, SUA.COMPANY_ID FROM SYS_USER_ALLOCATION SUA LEFT JOIN FND_EMPLOYEE_ASSIGNS FEA ON SUA.EMPLOYEE_ASSIGN_ID = FEA.EMPLOYEE_ASSIGN_ID LEFT JOIN FND_ORG_UNIT FOU ON FEA.UNIT_ID = FOU.UNIT_ID, ( SELECT MIN(COMPANY_ID) COMPANY_ID, USER_ID FROM SYS_USER_ALLOCATION GROUP BY USER_ID ORDER BY USER_ID ASC ) SUAC, FND_EMPLOYEE FE WHERE SUA.COMPANY_ID = FEA.COMPANY_ID AND SUA.COMPANY_ID = FOU.COMPANY_ID AND SUA.COMPANY_ID = SUAC.COMPANY_ID AND SUA.USER_ID = SUAC.USER_ID AND FE.EMPLOYEE_ID = FEA.EMPLOYEE_ID GROUP BY SUA.USER_ID, SUA.COMPANY_ID, FE. NAME ORDER BY SUA.USER_ID ASC ) TABALL1 on hmr.host_project_manager = TABALL1.USER_ID left join ( SELECT FE. NAME, SUA.USER_ID, MIN(FOU.UNIT_NAME) UNIT_NAME, SUA.COMPANY_ID FROM SYS_USER_ALLOCATION SUA LEFT JOIN FND_EMPLOYEE_ASSIGNS FEA ON SUA.EMPLOYEE_ASSIGN_ID = FEA.EMPLOYEE_ASSIGN_ID LEFT JOIN FND_ORG_UNIT FOU ON FEA.UNIT_ID = FOU.UNIT_ID, ( SELECT MIN(COMPANY_ID) COMPANY_ID, USER_ID FROM SYS_USER_ALLOCATION GROUP BY USER_ID ORDER BY USER_ID ASC ) SUAC, FND_EMPLOYEE FE WHERE SUA.COMPANY_ID = FEA.COMPANY_ID AND SUA.COMPANY_ID = FOU.COMPANY_ID AND SUA.COMPANY_ID = SUAC.COMPANY_ID AND SUA.USER_ID = SUAC.USER_ID AND FE.EMPLOYEE_ID = FEA.EMPLOYEE_ID GROUP BY SUA.USER_ID, SUA.COMPANY_ID, FE. NAME ORDER BY SUA.USER_ID ASC ) TABALL2 on hmr.assist_project_manager = TABALL2.USER_ID) t
1=1
and (t.created_by = #{createdBy} or EXISTS (SELECT 1 FROM sys_user U LEFT JOIN SYS_USER_ALLOCATION UR ON UR.USER_ID = U.USER_ID LEFT JOIN SYS_ROLE_B R ON R.ROLE_ID = UR.ROLE_ID WHERE R.ROLE_CODE = 'ADMIN' and U.USER_ID = #{createdBy}))
and t.marketing_report_number like concat(concat('%',#{marketingReportNumber}),'%')
and t.marketing_report_name like concat(concat('%',#{marketingReportName}),'%')
and nvl(t.credit_flag ,'N')=#{creditFlag,jdbcType=VARCHAR}
and t.estimated_financing_amount = #{estimatedFinancingAmount}
and t.tenant like concat(concat('%',#{tenant}),'%')
and t.other_bp_name like concat(concat('%',#{otherBpName}),'%')
and t.apply_leasing_products = #{applyLeasingProducts}
and t.host_project_manager = #{hostProjectManager}
and t.assist_project_manager = #{assistProjectManager}
and t.status = #{status}
and t.UNIT_ID = #{unitId}
and t.HOST_UNIT_NAME = #{hostUnitName}
and t.ASSIST_UNIT_NAME = #{assistUnitName}
and to_char(t.created_date,'yyyy/mm/dd') = to_char(#{approvedDate},'yyyy/mm/dd')
order by t.marketing_report_id desc

select * from ( select hmr.marketing_report_id,hmr.marketing_report_number,hmr.marketing_report_name,hmr.credit_flag,(SELECT v.meaning FROM sys_code_value_b_v v WHERE v.CODE = 'SYS.YES_NO' AND hmr.credit_flag = v.CODE_VALUE)credit_flag_n, (select LISTAGG(hbm.bp_name,',')WITHIN GROUP( ORDER BY hbm.bp_name) from hls_bp_master hbm,HLS_MARKETING_REPORT_bp hmrb where hbm.bp_id = hmrb.bp_id and hmrb.marketing_report_id = hmr.marketing_report_id and hmrb.bp_type in ('TENANT','TENANT_SEC')) tenant, (select LISTAGG(hbm.bp_name,',')WITHIN GROUP( ORDER BY hbm.bp_name) from hls_bp_master hbm,HLS_MARKETING_REPORT_bp hmrb where hbm.bp_id = hmrb.bp_id and hmrb.marketing_report_id = hmr.marketing_report_id and hmrb.bp_type = 'WARRANTOR') other_bp_name, hmr.unit_id, (select fou.unit_name from fnd_org_unit fou where fou.unit_id=hmr.unit_id) as unit_id_n, hmr.estimated_financing_amount, hmr.approved_date, hmr.approved_date+31 failure_date, hmr.apply_leasing_products, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v.code = 'HLS200.LEASING_PRODUCT_DETAIL' AND v.code_value = hmr.apply_leasing_products) apply_leasing_products_n, hmr.host_department_proportion, hmr.assist_department_proportion, hmr.host_project_manager, hmr.assist_project_manager, hmr.status, (SELECT meaning from sys_code_value_b_v where code = 'HLS_MARKETING' and code_value = hmr.status) status_n, TABALL1.NAME AS host_project_manager_n, hmr.host_unit_id, ( SELECT fou.unit_name FROM fnd_org_unit fou WHERE fou.unit_id = hmr.host_unit_id ) host_unit_name, hmr.assist_unit_id, TABALL2.NAME AS assist_project_manager_n, ( SELECT fou.unit_name FROM fnd_org_unit fou WHERE fou.unit_id = hmr.assist_unit_id ) assist_unit_name, hmr.creation_date, hmr.change_req_id from hls_marketing_report hmr left join ( SELECT FE. NAME, SUA.USER_ID, MIN(FOU.UNIT_NAME) UNIT_NAME, SUA.COMPANY_ID FROM SYS_USER_ALLOCATION SUA LEFT JOIN FND_EMPLOYEE_ASSIGNS FEA ON SUA.EMPLOYEE_ASSIGN_ID = FEA.EMPLOYEE_ASSIGN_ID LEFT JOIN FND_ORG_UNIT FOU ON FEA.UNIT_ID = FOU.UNIT_ID, ( SELECT MIN(COMPANY_ID) COMPANY_ID, USER_ID FROM SYS_USER_ALLOCATION GROUP BY USER_ID ORDER BY USER_ID ASC ) SUAC, FND_EMPLOYEE FE WHERE SUA.COMPANY_ID = FEA.COMPANY_ID AND SUA.COMPANY_ID = FOU.COMPANY_ID AND SUA.COMPANY_ID = SUAC.COMPANY_ID AND SUA.USER_ID = SUAC.USER_ID AND FE.EMPLOYEE_ID = FEA.EMPLOYEE_ID GROUP BY SUA.USER_ID, SUA.COMPANY_ID, FE. NAME ORDER BY SUA.USER_ID ASC ) TABALL1 on hmr.host_project_manager = TABALL1.USER_ID left join ( SELECT FE. NAME, SUA.USER_ID, MIN(FOU.UNIT_NAME) UNIT_NAME, SUA.COMPANY_ID FROM SYS_USER_ALLOCATION SUA LEFT JOIN FND_EMPLOYEE_ASSIGNS FEA ON SUA.EMPLOYEE_ASSIGN_ID = FEA.EMPLOYEE_ASSIGN_ID LEFT JOIN FND_ORG_UNIT FOU ON FEA.UNIT_ID = FOU.UNIT_ID, ( SELECT MIN(COMPANY_ID) COMPANY_ID, USER_ID FROM SYS_USER_ALLOCATION GROUP BY USER_ID ORDER BY USER_ID ASC ) SUAC, FND_EMPLOYEE FE WHERE SUA.COMPANY_ID = FEA.COMPANY_ID AND SUA.COMPANY_ID = FOU.COMPANY_ID AND SUA.COMPANY_ID = SUAC.COMPANY_ID AND SUA.USER_ID = SUAC.USER_ID AND FE.EMPLOYEE_ID = FEA.EMPLOYEE_ID GROUP BY SUA.USER_ID, SUA.COMPANY_ID, FE. NAME ORDER BY SUA.USER_ID ASC ) TABALL2 on hmr.assist_project_manager = TABALL2.USER_ID ) t
t.status in ('APPROVING','APPROVED','REJECTED')
and t.marketing_report_number like concat(concat('%',#{marketingReportNumber}),'%')
and t.tenant like concat(concat('%',#{tenant}),'%')
and t.other_bp_name like concat(concat('%',#{otherBpName}),'%')
and t.apply_leasing_products = #{applyLeasingProducts}
and t.host_project_manager = #{hostProjectManager}
and t.assist_project_manager = #{assistProjectManager}
and t.status = #{status}
and t.status_N = #{statusN}
and t.UNIT_ID = #{unitId}
and t.HOST_UNIT_NAME = #{hostUnitName}
and t.ASSIST_UNIT_NAME = #{assistUnitName}
order by t.marketing_report_id desc
